edits.newString:
const llmModel = resolveIVXAIModel() || 'openai/gpt-4o';
let knowledgeText = '';
if (streamCallback) {
  for await (const chunk of streamIVXAIText({
    module: 'owner-room-knowledge',
    requestId,
    model: llmModel,
    system: knowledgeSystemPrompt,
    prompt: knowledgePrompt,
    maxOutputTokens: 8_000,
  })) {
    if (chunk.type === 'delta' && chunk.delta) {
      knowledgeText += chunk.delta;
      streamCallback(chunk.delta);
    } else if (chunk.type === 'done') {
      knowledgeText = chunk.text ?? knowledgeText;
    }
  }
} else {
  const llmResult = await requestIVXAIText({
    module: 'owner-room-knowledge',
    requestId,
    model: llmModel,
    system: knowledgeSystemPrompt,
    prompt: knowledgePrompt,
    maxOutputTokens: 8_000,
  });
  knowledgeText = llmResult.text;
}
const answer = assertVisibleOwnerAIAnswer(knowledgeText);

